"""A tiny Caesar cipher utility."""


def encrypt(text: str, shift: int) -> str:
    """Return *text* with each character shifted by *shift* positions."""
    result = []
    shift = shift % 26
    for char in text:
        if "a" <= char <= "z":
            base = ord("a")
            result.append(chr(base + (ord(char) - base + shift) % 26))
        elif "A" <= char <= "Z":
            base = ord("A")
            result.append(chr(base + (ord(char) - base + shift) % 26))
        else:
            result.append(char)
    return "".join(result)
